#!/usr/bin/env python3
"""Emit the Wasm host adapter source; no inference runs in Python."""
from pathlib import Path
import sys

SOURCE = ';; Hand-written host adapter, not a Lean artifact theorem. All numerical\n;; conversions and greedy selection run in Wasm, never in the JS/C hosts.\n(module\n  (import "finish" "finish" (func $bias (param i64 i64) (result i64)))\n  (memory (export "memory") 1 1)\n  ;; 2984 binary64 weights at 0; f32 A/B/C at 24576/24640/28736;\n  ;; 256 binary64 logits at 29760. All regions are disjoint.\n  (func (export "weights") (local $i i32)\n    (loop $copy\n      (f32.store (i32.add (i32.const 24640) (i32.mul (local.get $i) (i32.const 4)))\n        (f32.demote_f64 (f64.load (i32.add (i32.const 13440) (i32.mul (local.get $i) (i32.const 8))))))\n      (local.set $i (i32.add (local.get $i) (i32.const 1)))\n      (br_if $copy (i32.lt_u (local.get $i) (i32.const 1024)))))\n  (func (export "prepare") (param $x0 i64) (param $x1 i64) (param $x2 i64) (param $x3 i64)\n    (f32.store (i32.const 24576) (f32.demote_f64 (f64.reinterpret_i64 (local.get $x0))))\n    (f32.store (i32.const 24580) (f32.demote_f64 (f64.reinterpret_i64 (local.get $x1))))\n    (f32.store (i32.const 24584) (f32.demote_f64 (f64.reinterpret_i64 (local.get $x2))))\n    (f32.store (i32.const 24588) (f32.demote_f64 (f64.reinterpret_i64 (local.get $x3)))))\n  (func (export "finish") (result i32)\n    (local $i i32) (local $best i32) (local $value f64) (local $maximum f64)\n    (local.set $maximum (f64.const -inf))\n    (loop $finish\n      (local.set $value (f64.reinterpret_i64 (call $bias\n        (i64.reinterpret_f64 (f64.promote_f32 (f32.load\n          (i32.add (i32.const 28736) (i32.mul (local.get $i) (i32.const 4))))))\n        (i64.load (i32.add (i32.const 21632) (i32.mul (local.get $i) (i32.const 8)))))))\n      ;; Reject NaNs and infinities rather than silently selecting a byte.\n      (if (f64.eq (f64.abs (local.get $value)) (f64.const inf)) (then unreachable))\n      (if (f64.ne (local.get $value) (local.get $value)) (then unreachable))\n      (f64.store (i32.add (i32.const 29760) (i32.mul (local.get $i) (i32.const 8))) (local.get $value))\n      (if (f64.gt (local.get $value) (local.get $maximum)) (then\n        (local.set $maximum (local.get $value)) (local.set $best (local.get $i))))\n      (local.set $i (i32.add (local.get $i) (i32.const 1)))\n      (br_if $finish (i32.lt_u (local.get $i) (i32.const 256))))\n    (local.get $best))\n)\n'

Path(sys.argv[1]).write_text(SOURCE)
